#include "gui/rename_rules.hpp"
#include "core/session.hpp"
#include "core/abif.hpp"
#include "abif_fixture.hpp"
#include <QCoreApplication>
#include <QRegularExpression>
#include <QSet>
#include <functional>
#include <iostream>
#include <sstream>
#include <stdexcept>
using namespace kleiotide;
namespace {void require(bool value,const char* text){if(!value)throw std::runtime_error(text);}template<class F>void rejects(F f){bool failed=false;try{f();}catch(const std::exception&){failed=true;}require(failed,"Expected invalid rename rejection");}}
int main(int argc,char** argv){QCoreApplication app(argc,argv);int passed=0,failed=0;auto run=[&](const char* label,const std::function<void()>& test){try{test();++passed;std::cout<<"PASS "<<label<<'\n';}catch(const std::exception& e){++failed;std::cerr<<"FAIL "<<label<<": "<<e.what()<<'\n';}};
run("Space conversion, literal prefix/suffix/replace and filename text",[]{Document d;d.load({{"Alpha one_two","A"}});RenameOptions o;auto plan=make_rename_plan(d,o);require(plan.rows[0].after=="Alpha_one_two","Spaces to underscores");o.operation=RenameOperation::UnderscoresToSpaces;require(make_rename_plan(d,o).rows[0].after=="Alpha one two","Underscores to spaces");o.operation=RenameOperation::Prepend;o.text="Жук ";require(make_rename_plan(d,o).rows[0].after=="Жук Alpha one_two","Unicode prefix");o.operation=RenameOperation::Append;o.text=" [sample]";require(make_rename_plan(d,o).rows[0].after=="Alpha one_two [sample]","Literal suffix");o.operation=RenameOperation::Replace;o.text="one";o.replacement="ONE";require(make_rename_plan(d,o).rows[0].after=="Alpha ONE_two","Case-sensitive literal replacement");o.operation=RenameOperation::Filename;o.text="reads";o.separator=" | ";require(make_rename_plan(d,o).rows[0].after=="Alpha one_two | reads","Editable filename text");});
run("Unicode reversal keeps emoji and combining graphemes intact",[]{Document d;d.load({{"Жук👩‍🔬é","A"}});RenameOptions o;o.operation=RenameOperation::Reverse;const auto p=make_rename_plan(d,o);require(p.rows[0].after==QString::fromUtf8("é👩‍🔬куЖ"),"Grapheme-safe reversal");});
run("Unique suffixes avoid original and unselected title collisions",[]{Document d;d.load({{"alpha","A"},{"alpha","C"},{"alpha_2","G"},{"alpha","T"}});RenameOptions o;o.operation=RenameOperation::Unique;auto p=make_rename_plan(d,o);require(p.changed==2&&p.duplicateRows==0&&p.rows[1].after=="alpha_3"&&p.rows[3].after=="alpha_4","Skip occupied numeric suffix");p=make_rename_plan(d,o,{2});require(p.rows.size()==1&&p.rows[0].after=="alpha_3"&&!p.rows[0].duplicate,"Selected names avoid outside collisions");o.operation=RenameOperation::StripSuffix;p=make_rename_plan(d,o);require(p.changed==1&&p.duplicateRows==4&&p.rows[2].after=="alpha","Numeric strip and collision reporting");});
run("Global row numbering and aligned/true lengths preserve selected scope",[]{Document d;d.load({{"one","A~-C"},{"two",""},{"mask","12~3",RowKind::Mask}});RenameOptions o;o.operation=RenameOperation::RowNumber;o.separator=" | ";auto p=make_rename_plan(d,o,{3,1});require(p.rows.size()==2&&p.rows[0].after=="one | 1"&&p.rows[1].after=="mask | 3","Current alignment row positions");o.operation=RenameOperation::Length;o.separator="_";p=make_rename_plan(d,o);require(p.rows[0].after=="one_4"&&p.rows[1].after=="two_0","Aligned lengths");o.operation=RenameOperation::TrueLength;p=make_rename_plan(d,o);require(p.rows[0].after=="one_2"&&p.rows[2].after=="mask_3","Mask and nucleotide nongap counts");});
run("Table mappings are exact, simultaneous and report missing/multiple matches",[]{Document d;d.load({{"A","A"},{"B","C"},{"A","G"}});RenameOptions o;o.operation=RenameOperation::Table;o.table="A\tB\r\nB\tC\nmissing\tother\nA\tB\n";auto p=make_rename_plan(d,o);require(p.changed==3&&p.rows[0].after=="B"&&p.rows[1].after=="C"&&p.rows[2].after=="B","Original-title matching is noncascading");require(p.unmatched==QStringList({"missing"})&&p.multipleMatches==1&&p.duplicateRows==2,"Missing/ambiguous/result duplicates reported");p=make_rename_plan(d,o,{2});require(p.rows[0].after=="C"&&p.unmatched==QStringList({"A","missing"}),"Missing reports respect scope");o.operation=RenameOperation::AppendTable;o.separator=" ";o.table="A\tTaxon alpha\n";p=make_rename_plan(d,o);require(p.rows[0].after=="A Taxon alpha"&&p.rows[1].after=="B","Taxonomy/text append table");});
run("Invalid names, conflicts, bad table rows and invalid scopes reject atomically",[]{Document d;d.load({{"one","A"},{"two","C"}});const auto state=d.state_id();RenameOptions o;o.operation=RenameOperation::Table;for(const auto& text:{QString{},QString("one\t"),QString("one\tx\ty"),QString("one\tx\none\ty"),QString("one\t  ")}){o.table=text;rejects([&]{make_rename_plan(d,o);});}o.operation=RenameOperation::Replace;o.text="one";o.replacement="";rejects([&]{make_rename_plan(d,o);});o.operation=RenameOperation::Append;o.text="\n";rejects([&]{make_rename_plan(d,o);});o.operation=RenameOperation::Unique;o.separator="";rejects([&]{make_rename_plan(d,o);});o.operation=RenameOperation::SpacesToUnderscores;rejects([&]{make_rename_plan(d,o,{1,1});});rejects([&]{make_rename_plan(d,o,{99});});require(d.state_id()==state&&!d.can_undo(),"Validation never changes data/history");});
run("Preview is read-only; atomic apply/undo retains traces, row IDs and masks",[]{std::istringstream in(test::synthetic_abif());Document d;d.load({read_abif(in,"trace name","fixture.ab1"),{"mask name","12",RowKind::Mask}});const auto trace=d.sequence(1).trace;const auto state=d.state_id();RenameOptions o;auto p=make_rename_plan(d,o);require(d.state_id()==state&&!d.can_undo()&&rename_plan_current(d,p),"Preview has no mutation");d.rename(p.patches());require(d.sequence(1).name=="trace_name"&&d.sequence(2).name=="mask_name"&&d.sequence(1).trace==trace,"One atomic name operation");require(!rename_plan_current(d,p),"Stale plan detected");d.undo();require(d.sequence(1).name=="trace name"&&d.sequence(2).name=="mask name"&&d.sequence(1).trace==trace&&d.sequence(2).kind==RowKind::Mask&&!d.can_undo(),"One undo restores all names only");d.redo();std::ostringstream out(std::ios::binary);write_session(out,d);std::istringstream saved(out.str(),std::ios::binary);const auto restored=read_session(saved);require(restored.document.sequence(1).name=="trace_name"&&restored.document.sequence(1).trace->original->channels==trace->original->channels,"Native names/evidence round trip");});
run("No-op plans produce no patches or undo records",[]{Document d;d.load({{"one","A"}});RenameOptions o;const auto p=make_rename_plan(d,o);require(p.changed==0&&p.patches().empty(),"No-op preview");d.rename(p.patches());require(!d.can_undo(),"No-op apply");});
run("Sanitize preserves safe titles and resolves punctuation/case/suffix collisions",[]{Document d;d.load({{"A B","A"},{"A_B","C"},{"A/B","G"},{"A_B_2","T"},{"a_b","A"},{"Жук","C"},{"sequence","G"},{"!!!","T"},{"123","A"},{"__","C"}});RenameOptions o;o.operation=RenameOperation::Sanitize;const auto p=make_rename_plan(d,o);require(p.rows[0].after=="A_B_3"&&p.rows[1].after=="A_B"&&p.rows[2].after=="A_B_4"&&p.rows[3].after=="A_B_2"&&p.rows[4].after=="a_b_5","Preserve original safe titles and skip reserved suffixes");require(p.rows[5].after=="sequence_2"&&p.rows[6].after=="sequence"&&p.rows[7].after=="sequence_3"&&p.rows[8].after=="123"&&p.rows[9].after=="__","Non-ASCII/punctuation fallback; safe numeric/underscore names unchanged");require(p.duplicateRows==0,"Sanitized targets unique");d.rename(p.patches());require(make_rename_plan(d,o).changed==0,"Sanitization is idempotent");});
run("Sanitize selected scope avoids untouched names and supports atomic undo",[]{Document d;d.load({{"alpha!","A"},{"alpha","C"},{"ALPHA_2","G"},{"alpha!","T"}});RenameOptions o;o.operation=RenameOperation::Sanitize;const auto p=make_rename_plan(d,o,{1,4});require(p.rows[0].after=="alpha_3"&&p.rows[1].after=="alpha_4","Case-insensitive collisions outside scope");const auto state=d.state_id();require(rename_plan_current(d,p)&&d.state_id()==state,"Read-only preview");d.rename(p.patches());require(d.sequence(2).name=="alpha"&&d.sequence(3).name=="ALPHA_2","Untouched scope retained");d.undo();require(d.sequence(1).name=="alpha!"&&d.sequence(4).name=="alpha!"&&!d.can_undo(),"One undo restores originals");});
run("Sanitize 2000 varied names yields ASCII-only unique idempotent results",[]{Document d;std::vector<Record> rows;for(unsigned i=0;i<2000;++i)rows.push_back({i%5==0?"Sample "+std::to_string(i%20):i%5==1?"Sample_"+std::to_string(i%20):i%5==2?"sample/"+std::to_string(i%20):i%5==3?"Жук 👩‍🔬":"!!!","A"});d.load(rows);RenameOptions o;o.operation=RenameOperation::Sanitize;const auto p=make_rename_plan(d,o);QSet<QString> names;const QRegularExpression allowed("^[A-Za-z0-9_]+$");for(const auto& row:p.rows){require(allowed.match(row.after).hasMatch(),"Requested ASCII character set");require(!names.contains(row.after.toCaseFolded()),"No exact or case-only duplicates");names.insert(row.after.toCaseFolded());}d.rename(p.patches());require(make_rename_plan(d,o).changed==0,"Second sanitization does not rename again");});
run("Group prefixes and suffixes respect scope, ungrouped rows and atomic undo",[]{Document d;d.load({{"one","A"},{"two","C"},{"three","G"}});d.apply_groups({{1,"North coast",0x112233}},{{1,1},{2,1}});RenameOptions o;o.operation=RenameOperation::AppendGroup;o.separator=" | ";auto p=make_rename_plan(d,o);require(p.changed==2&&p.rows[0].after=="one | North coast"&&p.rows[2].after=="three","Suffix and ungrouped semantics");d.rename(p.patches());d.undo();require(d.sequence(1).name=="one"&&d.sequence(2).groupId==1,"One undo retains groups");o.operation=RenameOperation::PrependGroup;o.separator="_";p=make_rename_plan(d,o,{2});require(p.rows.size()==1&&p.rows[0].after=="North coast_two","Selected prefix");d.rename(p.patches());d.undo();require(d.sequence(2).name=="two","Prefix undo");});
run("Table parser retains CRLF, duplicate titles, exact scope and one-step undo",[]{
    Document d;d.load({{"a","AC"},{"a","GT"},{"b","N"},{"a full header","T"}});
    RenameOptions options;options.operation=RenameOperation::Table;options.table="a\tb\r\nb\tc\r\nmissing\tx\n";
    const auto plan=make_rename_plan(d,options);require(plan.patches().size()==3,"Exact complete headers and duplicate titles");
    d.rename(plan.patches());require(d.sequence(1).name=="b"&&d.sequence(3).name=="c","Mappings do not cascade");
    d.undo();require(d.sequence(1).name=="a"&&d.sequence(3).name=="b"&&!d.can_undo(),"One undo restores all titles");
    options.table="a\tx";const auto scoped=make_rename_plan(d,options,{2});require(scoped.patches().size()==1&&scoped.patches()[0].first==2,"Selected duplicate only");
});
std::cout<<passed<<" passed; "<<failed<<" failed\n";return failed?1:0;}
